/**
 * Base block entity implementation for machines.
 * Implements Redstone Control and the Machine State system.
 */
public abstract class MachineBlockEntity extends EIOBlockEntity
        implements MenuProvider, Wrenchable, IOConfigurable, MachineInventoryHolder {

    public static final ICapabilityProvider<MachineBlockEntity, Direction, SideConfig> SIDE_CONFIG_PROVIDER = (be,
                                                                                                                side) -> side != null && be.isIOConfigMutable() ? new SidedIOConfigurable(be, side) : null;

    public static final ICapabilityProvider<MachineBlockEntity, Direction, IItemHandler> ITEM_HANDLER_PROVIDER = (be,
            side) -> be.inventory != null ? be.inventory.getForSide(side) : null;

    public static final ICapabilityProvider<BlockEntity, Void, SoulBindable> SOUL_BINDABLE = (be, ctx)
        -> be instanceof SoulBindable bindable ? bindable : null;

    private static final ModelProperty<IOConfigurable> IO_CONFIG_PROPERTY = LegacyMachineBlockEntity.IO_CONFIG_PROPERTY;

    @Nullable
    private final MachineInventory inventory;

    private IOConfig ioConfig;
    private final boolean isIoConfigMutable;

    private Set<MachineState> states = new HashSet<>();

    private RedstoneControl redstoneControl = RedstoneControl.ALWAYS_ACTIVE;
    private boolean isRedstoneBlocked;

    private final boolean supportsActiveState;

    @Nullable
    private UUID owner;

    public MachineBlockEntity(BlockEntityType<?> type, BlockPos worldPosition, BlockState blockState,
            boolean isIoConfigMutable) {
        super(type, worldPosition, blockState);

        this.isIoConfigMutable = isIoConfigMutable;
        this.ioConfig = getDefaultIOConfig();

        // Create inventory if the machine has a layout
        var layout = createInventoryLayout();
        if (layout != null) {
            inventory = createMachineInventory(layout);
        } else {
            inventory = null;
        }

        this.supportsActiveState = blockState.hasProperty(ProgressMachineBlock.POWERED);
    }

    /**
     * @return True if the machine is active, this applies the POWERED block state if available.
     */
    public abstract boolean isActive();

    @Override
    public void serverTick() {
        super.serverTick();

        if (canAct(distributeResourcesInterval())) {
            distributeResources();
        }

        // Every 5 ticks, ensure active state is up-to-date.
        // Doing this every 5 ticks instead of every tick should reduce visual flicker.
        if (level != null && level.getGameTime() % 5 == 0) {

            boolean isActive = isActive();
            boolean needBlockStateUpdate = supportsActiveState
                    && getBlockState().getValue(ProgressMachineBlock.POWERED) != isActive;
            boolean needStateUpdate = states.contains(MachineState.ACTIVE) != isActive;

            if (needBlockStateUpdate) {
                level.setBlockAndUpdate(worldPosition,
                        getBlockState().setValue(ProgressMachineBlock.POWERED, isActive));
            }

            if (needStateUpdate) {
                updateMachineState(MachineState.ACTIVE, isActive);
            }
        }
    }

    /**
     * Get the facing direction of the machine.
     */
    protected final Direction getBlockFacing() {
        BlockState state = getBlockState();
        if (state.hasProperty(LegacyMachineBlock.FACING)) {
            return getBlockState().getValue(LegacyMachineBlock.FACING);
        }

        return Direction.SOUTH;
    }

    // region Ticking Control

    public boolean canAct() {
        if (level == null) {
            return false;
        }

        return !isRedstoneBlocked();
    }

    public boolean canAct(int interval) {
        return level != null && canAct() && level.getGameTime() % interval == 0;
    }

    // endregion

    // region Inventory

    /**
     * Define the slot layout for the machine.
     * @return The slot layout or null for no inventory.
     */
    @Nullable
    protected MachineInventoryLayout createInventoryLayout() {
        return null;
    }

    /**
     * @apiNote inventories should call {@link MachineBlockEntity#onInventoryContentsChanged}!
     */
    protected MachineInventory createMachineInventory(MachineInventoryLayout layout) {
        return new MachineInventory(this, layout) {
            @Override
            protected void onContentsChanged(int slot) {
                onInventoryContentsChanged(slot);
                setChanged();
            }

            @Override
            public void updateMachineState(MachineState state, boolean add) {
                MachineBlockEntity.this.updateMachineState(state, add);
            }
        };
    }

    public final MachineInventory getInventory() {
        if (!hasInventory()) {
            throw new IllegalStateException("This machine does not have an inventory.");
        }

        return inventory;
    }

    public final boolean hasInventory() {
        return inventory != null;
    }

    /**
     * @apiNote Must call this on custom MachineInventory handlers!
     */
    protected void onInventoryContentsChanged(int slot) {
    }

    // endregion

    // region IO Config

    public IOConfig getDefaultIOConfig() {
        return IOConfig.empty();
    }

    public final IOConfig getIOConfig() {
        if (isIOConfigMutable()) {
            return ioConfig;
        }

        return getDefaultIOConfig();
    }

    private void setIOConfig(IOConfig ioConfig) {
        this.ioConfig = ioConfig;

        if (level != null) {
            setChanged();
            level.sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), Block.UPDATE_ALL);
        }
    }

    // region IOConfigurable Implementation

    @Override
    public IOMode getIOMode(Direction side) {
        return getIOConfig().getMode(translateIOSide(side));
    }

    @Override
    public final boolean isIOConfigMutable() {
        return isIoConfigMutable;
    }

    @Override
    public boolean shouldRenderIOConfigOverlay() {
        return isIOConfigMutable();
    }

    @Override
    public void setIOMode(Direction side, IOMode mode) {
        if (!isIOConfigMutable()) {
            throw new IllegalStateException("Cannot edit fixed IO mode.");
        }

        if (!supportsIOMode(side, mode)) {
            throw new IllegalStateException("Cannot use this mode on this side.");
        }

        Direction localSide = translateIOSide(side);
        setIOConfig(ioConfig.withMode(localSide, mode));

        // Invalidate caps
        level.invalidateCapabilities(worldPosition);
        level.sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), Block.UPDATE_ALL);
    }

    @Override
    public ModelData getModelData() {
        if (!shouldRenderIOConfigOverlay()) {
            return ModelData.EMPTY;
        }

        return ModelData.builder().with(IO_CONFIG_PROPERTY, this).build();
    }

    @UseOnly(LogicalSide.CLIENT)
    private void clientIOConfigChanged() {
        if (shouldRenderIOConfigOverlay()) {
            requestModelDataUpdate();
        }

        level.sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), Block.UPDATE_ALL);
    }

    @Override
    public boolean supportsIOMode(Direction side, IOMode state) {
        return true;
    }

    private Direction translateIOSide(Direction side) {
        // The block faces with its southern face. So the back of the machine.
        Direction south = getBlockFacing();
        return switch (side) {
        case NORTH -> south.getOpposite();
        case SOUTH -> south;
        case WEST -> south.getCounterClockWise();
        case EAST -> south.getClockWise();
        default -> side;
        };
    }

    // endregion

    // endregion

    public void setMachineOwner(UUID owner) {
        this.owner = owner;
        setChanged();
    }

    @Nullable
    public UUID getMachineOwner() {
        return this.owner;
    }

    public UUID getMachineOwnerOrRandom() {
        return Objects.requireNonNullElseGet(getMachineOwner(), UUID::randomUUID);
    }

    // region Resource Distribution

    // TODO: I kind of want to rewrite this without relying on getSelfCapability.

    /**
     * If you distribute resources faster than a normal machine, set the minimum interval here.
     */
    protected int distributeResourcesInterval() {
        return 5;
    }

    @UseOnly(LogicalSide.SERVER)
    protected void distributeResources() {
        // TODO: Quick way to see if any sides are set to force.

        for (Direction side : Direction.values()) {
            IOMode mode = getIOMode(side);
            if (mode.canForce()) {
                distributeResources(side);
            }
        }
    }

    protected void distributeResources(Direction side) {
        if (canAct(20)) {
            distributeItems(side);
        }

        if (canAct(5)) {
            distributeFluids(side);
        }
    }

    private void distributeItems(Direction side) {
        IItemHandler selfHandler = getSelfCapability(Capabilities.ItemHandler.BLOCK, side);
        IItemHandler otherHandler = getNeighbouringCapability(Capabilities.ItemHandler.BLOCK, side);
        if (selfHandler == null || otherHandler == null) {
            return;
        }

        TransferUtil.distributeItems(getIOMode(side), selfHandler, otherHandler);
    }

    private void distributeFluids(Direction side) {
        IFluidHandler selfHandler = getSelfCapability(Capabilities.FluidHandler.BLOCK, side);
        IFluidHandler otherHandler = getNeighbouringCapability(Capabilities.FluidHandler.BLOCK, side);
        if (selfHandler == null || otherHandler == null) {
            return;
        }

        TransferUtil.distributeFluids(getIOMode(side), selfHandler, otherHandler);
    }

    // endregion

    // region Machine States

    public Set<MachineState> getMachineStates() {
        return states;
    }

    @UseOnly(LogicalSide.CLIENT)
    public void clientSetMachineStates(Set<MachineState> states) {
        if (level == null) {
            return;
        }

        this.states = states;
    }

    protected void updateMachineState(MachineState state, boolean predicate) {
        if (predicate) {
            pushMachineState(state);
        } else {
            popMachineState(state);
        }
    }

    @UseOnly(LogicalSide.SERVER)
    protected void pushMachineState(MachineState state) {
        if (level == null) {
            return;
        }

        states.add(state);
        level.sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), Block.UPDATE_ALL);
    }

    @UseOnly(LogicalSide.SERVER)
    protected void popMachineState(MachineState state) {
        if (level == null) {
            return;
        }

        if (states.remove(state)) {
            level.sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), Block.UPDATE_ALL);
        }
    }

    // endregion

    // region Redstone Control

    // TODO: Maybe put this into a constructor parameter instead.
    /**
     * Whether the machine can be controlled by Redstone.
     * Do not turn on/off dynamically.
     */
    public boolean supportsRedstoneControl() {
        return true;
    }

    /**
     * @return The redstone control mode for the machine
     * @throws IllegalStateException if the machine does not support redstone control.
     */
    public final RedstoneControl getRedstoneControl() {
        if (!supportsRedstoneControl()) {
            throw new IllegalStateException("This machine does not support redstone control.");
        }

        return redstoneControl;
    }

    public void setRedstoneControl(RedstoneControl control) {
        redstoneControl = control;
        setChanged();
        checkIsRedstoneBlocked();
    }

    // Final, handoff to supportsRedstoneControl now.
    @Override
    protected final boolean supportsRedstonePower() {
        return supportsRedstoneControl();
    }

    @Override
    protected void updateRedstonePower() {
        super.updateRedstonePower();
        checkIsRedstoneBlocked();
    }

    private void checkIsRedstoneBlocked() {
        if (supportsRedstoneControl()) {
            isRedstoneBlocked = !redstoneControl.isActive(isRedstonePowered());
            updateMachineState(MachineState.REDSTONE, isRedstoneBlocked);
        }
    }

    protected boolean isRedstoneBlocked() {
        return isRedstoneBlocked;
    }

    // endregion

    // region Wrenchable Implementation

    @Override
    public ItemInteractionResult onWrenched(UseOnContext context) {
        var player = context.getPlayer();
        if (player == null || level == null) {
            return ItemInteractionResult.SUCCESS;
        }

        // Holding shift
        if (player.isSecondaryUseActive()) {
            BlockPos pos = getBlockPos();
            BlockState state = getBlockState();
            Block block = state.getBlock();

            if (level instanceof ServerLevel serverLevel) {
                List<ItemStack> drops = Block.getDrops(state, serverLevel, pos, serverLevel.getBlockEntity(pos));
                Inventory inventory = player.getInventory();
                for (ItemStack item : drops) {
                    inventory.placeItemBackInInventory(item);
                }
            }

            block.playerWillDestroy(level, pos, state, player);
            level.removeBlock(pos, false);
            block.destroy(level, pos, state);

            // TODO: custom sound when sound manager is up and running??

            return ItemInteractionResult.sidedSuccess(level.isClientSide());
        } else {
            if (level.isClientSide()) {
                if (isIOConfigMutable()) {
                    PacketDistributor.sendToServer(new ServerboundCycleIOConfigPacket(worldPosition, context.getClickedFace()));
                }
            }

            return ItemInteractionResult.sidedSuccess(level.isClientSide());
        }
    }

    // endregion

    // region Menu Provider Implementation

    @Override
    public Component getDisplayName() {
        // Default the menu title to the name of the machine's block.
        return getBlockState().getBlock().getName();
    }

    // endregion

    // region Serialization

    @Override
    protected void saveAdditional(CompoundTag tag, HolderLookup.Provider registries) {
        super.saveAdditional(tag, registries);

        if (supportsRedstoneControl()) {
            tag.put(MachineNBTKeys.REDSTONE_CONTROL, redstoneControl.save(registries));
        }

        if (hasInventory()) {
            tag.put(MachineNBTKeys.ITEMS, inventory.serializeNBT(registries));
        }
    }

    // Opt into network syncing
    @Override
    public @Nullable Packet<ClientGamePacketListener> getUpdatePacket() {
        return ClientboundBlockEntityDataPacket.create(this);
    }

    @Override
    protected void saveAdditionalSynced(CompoundTag tag, HolderLookup.Provider registries) {
        super.saveAdditionalSynced(tag, registries);

        if (isIoConfigMutable && ioConfig != null) {
            tag.put(MachineNBTKeys.IO_CONFIG, ioConfig.save(registries));
        }

        if (owner != null) {
            tag.putUUID(MachineNBTKeys.OWNER, this.owner);
        }
    }

    @SuppressWarnings("removal")
    @Override
    protected void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
        super.loadAdditional(tag, registries);

        if (hasInventory() && tag.contains(MachineNBTKeys.ITEMS)) {
            inventory.deserializeNBT(registries, tag.getCompound(MachineNBTKeys.ITEMS));
        }

        // Supports old attachments.
        // We've been misusing attachments, they're intended for 3rd party data
        // additions
        // Reverting this will take some time

        // Same for IO Config
        // TODO: Ender IO 8 - remove.
        if (hasData(EIOAttachments.IO_CONFIG)) {
            ioConfig = getData(EIOAttachments.IO_CONFIG);
            removeData(EIOAttachments.IO_CONFIG);
        } else if (tag.contains(MachineNBTKeys.IO_CONFIG)) {
            ioConfig = IOConfig.parseOptional(registries, tag.getCompound(MachineNBTKeys.IO_CONFIG));

            if (level != null && level.isClientSide) {
                clientIOConfigChanged();
            }
        }

        if (supportsRedstoneControl()) {
            // TODO: Ender IO 8 - remove.
            if (hasData(EIOAttachments.REDSTONE_CONTROL)) {
                redstoneControl = getData(EIOAttachments.REDSTONE_CONTROL);
                removeData(EIOAttachments.REDSTONE_CONTROL);
            } else if (tag.contains(MachineNBTKeys.REDSTONE_CONTROL)) {
                redstoneControl = RedstoneControl.parse(registries,
                        Objects.requireNonNull(tag.get(MachineNBTKeys.REDSTONE_CONTROL)));
            }
        }

        if (tag.contains(MachineNBTKeys.OWNER)) {
            owner = tag.getUUID(MachineNBTKeys.OWNER);
        }
    }

    @Override
    protected void applyImplicitComponents(DataComponentInput componentInput) {
        super.applyImplicitComponents(componentInput);

        if (hasInventory()) {
            this.inventory
                    .copyFromItem(componentInput.getOrDefault(DataComponents.CONTAINER, ItemContainerContents.EMPTY));
        }

        if (isIOConfigMutable()) {
            ioConfig = componentInput.getOrDefault(EIODataComponents.IO_CONFIG, IOConfig.empty());
        }

        if (supportsRedstoneControl()) {
            var redstoneControl = componentInput.get(EIODataComponents.REDSTONE_CONTROL);
            if (redstoneControl != null) {
                this.redstoneControl = redstoneControl;
            }
        }
    }

    @Override
    protected void collectImplicitComponents(DataComponentMap.Builder components) {
        super.collectImplicitComponents(components);

        if (hasInventory()) {
            components.set(DataComponents.CONTAINER, this.inventory.toItemContents());
        }

        if (isIOConfigMutable()) {
            components.set(EIODataComponents.IO_CONFIG, ioConfig);
        }

        if (supportsRedstoneControl()) {
            components.set(EIODataComponents.REDSTONE_CONTROL, redstoneControl);
        }
    }

    @SuppressWarnings("deprecation")
    @Override
    public void removeComponentsFromTag(CompoundTag tag) {
        super.removeComponentsFromTag(tag);
        tag.remove(MachineNBTKeys.ITEMS);
        tag.remove(MachineNBTKeys.IO_CONFIG);
        tag.remove(MachineNBTKeys.REDSTONE_CONTROL);
    }

    // endregion
}

package com.enderio.enderio.foundation.block.entity;

import com.enderio.enderio.api.EnderIOCapabilities;
import com.enderio.core.annotations.UseOnly;
import com.enderio.enderio.api.capacitor.CapacitorData;
import com.enderio.enderio.api.capacitor.CapacitorScalable;
import com.enderio.enderio.api.io.energy.EnergyIOMode;
import com.enderio.enderio.content.capacitors.CapacitorItem;
import com.enderio.enderio.foundation.MachineNBTKeys;
import com.enderio.enderio.foundation.block.entity.flags.CapacitorSupport;
import com.enderio.enderio.foundation.energy.PoweredMachineEnergyStorage;
import com.enderio.enderio.foundation.inventory.MachineInventory;
import com.enderio.enderio.foundation.io.TransferUtil;
import com.enderio.enderio.foundation.state.MachineState;
import com.enderio.enderio.init.EIODataComponents;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.HolderLookup;
import net.minecraft.core.component.DataComponentMap;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.IntTag;
import net.minecraft.nbt.Tag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.minecraft.world.level.block.state.BlockState;
import net.neoforged.fml.LogicalSide;
import net.neoforged.neoforge.capabilities.ICapabilityProvider;
import net.neoforged.neoforge.energy.IEnergyStorage;

public abstract class PoweredMachineBlockEntity extends MachineBlockEntity implements MachineInstallable {

    public static final ICapabilityProvider<PoweredMachineBlockEntity, Direction, IEnergyStorage> ENERGY_STORAGE_PROVIDER = (
            be, side) -> side == null ? be.energyStorage : be.energyStorage.getSided(side);

    private final CapacitorSupport capacitorSupport;
    private CapacitorData capacitorData = CapacitorData.NONE;
    private boolean isCapacitorDataDirty;

    private final EnergyIOMode energyIOMode;
    private final CapacitorScalable scalableEnergyCapacity;
    private final CapacitorScalable scalableMaxEnergyUse;

    private final PoweredMachineEnergyStorage energyStorage;

    public PoweredMachineBlockEntity(BlockEntityType<?> type, BlockPos worldPosition, BlockState blockState,
                                     boolean isIoConfigMutable, CapacitorSupport capacitorSupport, EnergyIOMode energyIOMode,
                                     CapacitorScalable scalableEnergyCapacity, CapacitorScalable scalableMaxEnergyUse) {
        super(type, worldPosition, blockState, isIoConfigMutable);

        this.capacitorSupport = capacitorSupport;
        this.energyIOMode = energyIOMode;
        this.scalableEnergyCapacity = scalableEnergyCapacity;
        this.scalableMaxEnergyUse = scalableMaxEnergyUse;

        // Sanity check for capacitors.
        if (supportsCapacitor() && (!hasInventory() || !getInventory().layout().supportsCapacitor())) {
            throw new IllegalStateException(
                    "A machine which accepts a capacitor must have an inventory with a capacitor slot!");
        }

        energyStorage = new PoweredMachineEnergyStorage(this);
    }

    @Override
    public void onLoad() {
        super.onLoad();
        updatePowerState();
        updateCapacitorState();
    }

    @Override
    public void setLevel(Level level) {
        super.setLevel(level);
        updatePowerState();
        updateCapacitorData();
    }

    @Override
    public void setChanged() {
        super.setChanged();
        updatePowerState();
    }

    @Override
    protected void onInventoryContentsChanged(int slot) {
        super.onInventoryContentsChanged(slot);
        updateCapacitorData();
    }

    // region Energy Storage

    public PoweredMachineEnergyStorage getEnergyStorage() {
        return energyStorage;
    }

    @UseOnly(LogicalSide.CLIENT)
    public final void clientSetEnergyStored(int energyStored) {
        energyStorage.setEnergyStored(energyStored);
    }

    public final boolean hasEnergy() {
        // If the machine has no capacitor, you cannot interact with it's energy storage
        if (requiresCapacitor() && !isCapacitorInstalled()) {
            return false;
        }

        return energyStorage.getEnergyStored() > 0;
    }

    public final int getMaxEnergyStored() {
        // TODO: Scalable might need redesigned to just scale directly...
        return scalableEnergyCapacity.scaleI(this::getCapacitorData).get();
    }

    public final int getMaxEnergyUse() {
        return scalableMaxEnergyUse.scaleI(this::getCapacitorData).get();
    }

    public final EnergyIOMode energyIOMode() {
        return energyIOMode;
    }

    protected void updatePowerState() {
        updateMachineState(MachineState.NO_POWER, energyStorage.getEnergyStored() <= 0);
    }

    // region Distribution

    @Override
    protected int distributeResourcesInterval() {
        return energyIOMode.canOutput() ? 1 : super.distributeResourcesInterval();
    }

    @Override
    protected void distributeResources() {
        super.distributeResources();

        if (energyIOMode.canOutput()) {
            TransferUtil.distributeEnergyEvenly(level, worldPosition, dir -> energyIOMode.canPush(getIOMode(dir)));
        }
    }

    // endregion

    // endregion

    // region Capacitor

    public final CapacitorSupport capacitorSupport() {
        return capacitorSupport;
    }

    public final boolean supportsCapacitor() {
        return capacitorSupport != CapacitorSupport.NONE;
    }

    public final boolean requiresCapacitor() {
        return capacitorSupport == CapacitorSupport.REQUIRED;
    }

    public boolean isCapacitorInstalled() {
        if (!supportsCapacitor()) {
            // TODO: Should this be an exception because we do not support capacitors?
            return false;
        }

        if (level != null && level.isClientSide()) {
            return !getCapacitorItem().isEmpty();
        }

        if (isCapacitorDataDirty) {
            updateCapacitorData();
        }

        return !capacitorData.equals(CapacitorData.NONE);
    }

    @UseOnly(LogicalSide.SERVER)
    public CapacitorData getCapacitorData() {
        if (!supportsCapacitor()) {
            throw new IllegalStateException("Unable to get capacitor data, this machine does not support capacitors!");
        }

        if (isCapacitorDataDirty) {
            updateCapacitorData();
        }

        return capacitorData;
    }

    public final ItemStack getCapacitorItem() {
        MachineInventory inventory = getInventory();
        if (inventory == null) {
            return ItemStack.EMPTY;
        }

        return inventory.getStackInSlot(inventory.layout().getCapacitorSlot());
    }

    public final int getCapacitorSlotIndex() {
        if (!hasInventory()) {
            throw new IllegalStateException("Attempt to get capacitor slot for machine with no inventory!");
        }

        var layout = getInventory().layout();
        if (!layout.supportsCapacitor()) {
            throw new IllegalStateException("Unable to get capacitor slot index, inventory has no capacitor slot.");
        }

        return layout.getCapacitorSlot();
    }

    protected void updateCapacitorData() {
        // Wait for the level to be loaded.
        if (level == null) {
            return;
        }

        isCapacitorDataDirty = false;

        if (supportsCapacitor()) {
            var capacitorItem = getCapacitorItem();
            var capacitorExtension = capacitorItem.getCapability(EnderIOCapabilities.CAPACITOR_EXTENSION);
            if (capacitorExtension != null) {
                capacitorData = capacitorExtension.getCapacitorData(capacitorItem, level.registryAccess());
            } else {
                capacitorData = getCapacitorItem().getOrDefault(EIODataComponents.CAPACITOR_DATA, CapacitorData.NONE);
            }

            updateCapacitorState();
        }
    }

    private void updateCapacitorState() {
        updateMachineState(MachineState.NO_CAPACITOR, supportsCapacitor() && !isCapacitorInstalled());
    }

    // TODO: Ensure this is called by all machines.
    protected void onMachineUsed() {
        if (supportsCapacitor()) {
            if (!(level instanceof ServerLevel serverLevel)) {
                return;
            }

            var capacitorItem = getCapacitorItem();
            var capacitorExtension = capacitorItem.getCapability(EnderIOCapabilities.CAPACITOR_EXTENSION);
            if (capacitorExtension != null) {
                capacitorExtension.onMachineUsed(capacitorItem, serverLevel);
            }
        }
    }

    // region MachineInstallable Implementation

    @Override
    public InteractionResult tryItemInstall(ItemStack stack, UseOnContext context) {
        if (stack.getItem() instanceof CapacitorItem && supportsCapacitor() && !isCapacitorInstalled()) {
            MachineInventory inventory = getInventory();
            if (inventory != null) {
                inventory.setStackInSlot(inventory.layout().getCapacitorSlot(), stack.copyWithCount(1));
                stack.shrink(1);
                return InteractionResult.sidedSuccess(context.getLevel().isClientSide());
            }
        }

        return InteractionResult.PASS;
    }

    // endregion

    // endregion

    // region Serialization

    @Override
    protected void saveAdditional(CompoundTag tag, HolderLookup.Provider registries) {
        super.saveAdditional(tag, registries);
        tag.put(MachineNBTKeys.ENERGY_STORED, energyStorage.serializeNBT(registries));
    }

    @Override
    protected void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
        super.loadAdditional(tag, registries);

        if (tag.contains(MachineNBTKeys.ENERGY_STORED, Tag.TAG_INT)) {
            energyStorage.deserializeNBT(registries, (IntTag) tag.get(MachineNBTKeys.ENERGY_STORED));
        } else if (tag.contains(MachineNBTKeys.ENERGY, Tag.TAG_COMPOUND)) {
            // SUPPORT LEGACY STORAGE FORMAT
            CompoundTag energyTag = tag.getCompound(MachineNBTKeys.ENERGY);

            if (energyTag.contains(MachineNBTKeys.ENERGY_STORED)) {
                energyStorage.setEnergyStored(energyTag.getInt(MachineNBTKeys.ENERGY_STORED));
            }
        }

        updateCapacitorData();
    }

    @Override
    protected void applyImplicitComponents(DataComponentInput componentInput) {
        super.applyImplicitComponents(componentInput);
        energyStorage.setEnergyStored(componentInput.getOrDefault(EIODataComponents.ENERGY, 0));
        updateCapacitorData();
    }

    @Override
    protected void collectImplicitComponents(DataComponentMap.Builder components) {
        super.collectImplicitComponents(components);
        components.set(EIODataComponents.ENERGY, energyStorage.getEnergyStored());
    }

    @Override
    public void removeComponentsFromTag(CompoundTag tag) {
        super.removeComponentsFromTag(tag);
        tag.remove(MachineNBTKeys.ENERGY_STORED);
    }

    // endregion
}
